#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 18
#define MAXM 100005

int n, m;
int a[MAXM], b[MAXM];
int dp[1 << MAXN];
int cnt[1 << MAXN];

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) {
        scanf("%d %d", &a[i], &b[i]);
    }

    int total = 1 << n;
    // cnt[mask] = number of teams in mask
    for (int mask = 1; mask < total; mask++) {
        cnt[mask] = cnt[mask >> 1] + (mask & 1);
    }

    // Precompute which masks are "valid" segments: they appear in input as a contiguous segment
    // We'll store for each mask the number of times it appears as a segment (but we only need existence)
    int valid[1 << MAXN] = {0};
    for (int i = 0; i < m; i++) {
        int mask = 0;
        for (int j = a[i]; j <= b[i]; j++) {
            mask |= (1 << j);
        }
        valid[mask] = 1;
    }

    memset(dp, 0x3f, sizeof(dp));
    dp[0] = 0;

    for (int mask = 0; mask < total; mask++) {
        if (dp[mask] > total) continue;
        // Try to add a valid segment that is a subset of the remaining teams
        int remaining = (total - 1) ^ mask;
        // Enumerate submasks of remaining
        int sub = remaining;
        while (sub) {
            if (valid[sub]) {
                int newmask = mask | sub;
                int cost = cnt[sub] - 1; // need to change all but one to match the segment
                if (dp[newmask] > dp[mask] + cost) {
                    dp[newmask] = dp[mask] + cost;
                }
            }
            sub = (sub - 1) & remaining;
        }
    }

    // The answer is dp[total - 1] (all teams assigned)
    printf("%d\n", dp[total - 1]);
    return 0;
}

