int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int total_teams = 1 << n;
    int num_slots = n + 1;
    // valid sizes: 1, 1, 2, 4, ..., 2^(n-1)
    int vsize[65];
    vsize[0] = 1; vsize[1] = 1;
    for (int i = 2; i <= n; i++) vsize[i] = 1 << (i-1);

    int g[100005];
    for (int i = 0; i < m; i++) {
        int a, b; scanf("%d %d", &a, &b);
        g[i] = b - a + 1;
    }

    // dp[j] = max teams kept using first j valid slots
    long long dp[65];
    memset(dp, 0, sizeof(dp));

    // For each group in order, update dp
    // dp[j] = max over assignments
    for (int i = 0; i < m; i++) {
        for (int j = num_slots; j >= 1; j--) {
            int keep = g[i] < vsize[j-1] ? g[i] : vsize[j-1];
            if (dp[j-1] + keep > dp[j]) dp[j] = dp[j-1] + keep;
        }
    }

    long long best = dp[num_slots];
    printf("%d\n", total_teams - (int)best);
    return 0;
}

