#define INF 1000000000

static int popcount_int(unsigned x) {
    int c = 0;
    while (x) {
        c += x & 1u;
        x >>= 1u;
    }
    return c;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int N = 1 << n;                 /* number of teams */
    int *rankv = (int*)malloc(N * sizeof(int));

    int pos = 0;
    for (int i = 0; i < m; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        for (int j = 0; j < b; ++j) {
            if (pos < N) rankv[pos++] = a;
        }
    }

    /* cnt[mask][r] = number of teams inside subset mask having received rank r
       only masks of size power-of-two are used, but storing all is simpler */
    int *cnt = (int*)calloc((size_t)(1 << N) ? 1 : 1, 1); /* dummy to avoid warnings */
    free(cnt);

    int masks = 1 << N;
    int *best = (int*)malloc(masks * sizeof(int));
    for (int i = 0; i < masks; ++i) best[i] = INF;

    /* precompute frequency of ranks for every mask */
    int *freq = (int*)calloc((size_t)masks * n, sizeof(int));
    for (int mask = 1; mask < masks; ++mask) {
        int b = __builtin_ctz((unsigned)mask);
        int pmask = mask ^ (1 << b);
        memcpy(&freq[mask * n], &freq[pmask * n], n * sizeof(int));
        int r = rankv[b];
        if (0 <= r && r < n) freq[mask * n + r]++;
    }

    /* valid block sizes are powers of two */
    for (int mask = 1; mask < masks; ++mask) {
        int sz = popcount_int((unsigned)mask);
        if ((sz & (sz - 1)) != 0) continue; /* not power of two */

        int k = 0;
        while ((1 << k) < sz) k++;
        int expected = n - k; /* all teams in this block must have this rank */
        if (sz == 1) {
            best[mask] = (rankv[__builtin_ctz((unsigned)mask)] == expected) ? 0 : 1;
            continue;
        }

        int keep = freq[mask * n + expected];
        int cost_here = sz - keep;

        int half = sz >> 1;
        int sub = (mask - 1) & mask;
        while (sub) {
            if (popcount_int((unsigned)sub) == half) {
                int other = mask ^ sub;
                if (sub < other) {
                    int cand = best[sub] + best[other] + cost_here;
                    if (cand < best[mask]) best[mask] = cand;
                }
            }
            sub = (sub - 1) & mask;
        }
    }

    printf("%d\n", best[masks - 1]);

    free(rankv);
    free(best);
    free(freq);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int solve(const vector<int>& rank, int l, int r) {
    int len = r - l;
    if (len == 1) return 0;
    int mid = (l + r) / 2;
    int leftCount = 0, rightCount = 0;
    for (int i = l; i < mid; ++i) {
        if (rank[i] >= l && rank[i] < mid) leftCount++;
    }
    for (int i = mid; i < r; ++i) {
        if (rank[i] >= mid && rank[i] < r) rightCount++;
    }
    int half = len / 2;
    int option1 = (half - leftCount) + (half - rightCount) 
                  + solve(rank, l, mid) + solve(rank, mid, r);
    // swapped order: left half should contain right subtree numbers, and vice versa
    int leftCountSwapped = 0, rightCountSwapped = 0;
    for (int i = l; i < mid; ++i) {
        if (rank[i] >= mid && rank[i] < r) leftCountSwapped++;
    }
    for (int i = mid; i < r; ++i) {
        if (rank[i] >= l && rank[i] < mid) rightCountSwapped++;
    }
    int option2 = (half - leftCountSwapped) + (half - rightCountSwapped) 
                  + solve(rank, l, mid) + solve(rank, mid, r);
    return min(option1, option2);
}

