import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int totalTeams = 1 << n; // 2^n teams

        // Read the segments: each segment gives the same rank for teams from a to b inclusive
        int[] rank = new int[totalTeams];
        Arrays.fill(rank, -1);
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int r = Integer.parseInt(st.nextToken());
            for (int j = a; j <= b; j++) {
                rank[j] = r;
            }
        }

        // dp[mask] = maximum number of teams in the subtree rooted at mask
        // that already have correct rank consistent with tournament outcome
        int[] dp = new int[totalTeams * 2]; // we'll use indices 1..2*totalTeams-1 for tree nodes
        // leaves are at indices totalTeams .. 2*totalTeams-1
        int size = totalTeams * 2;
        int[] nodeRank = new int[size];
        Arrays.fill(nodeRank, -1);

        // Initialize leaves with given rank
        for (int i = 0; i < totalTeams; i++) {
            nodeRank[totalTeams + i] = rank[i];
        }

        // Process internal nodes bottom-up
        for (int i = totalTeams - 1; i >= 1; i--) {
            int left = 2 * i;
            int right = 2 * i + 1;
            int leftRank = nodeRank[left];
            int rightRank = nodeRank[right];
            int best = 0;

            // If left and right both have same rank, we can keep both (match between equal ranks)
            if (leftRank != -1 && leftRank == rightRank) {
                best = dp[left] + dp[right] + 2; // both can stay with same rank
            }

            // Option: pick left winner, right must have lower rank (or -1)
            if (leftRank != -1 && (rightRank == -1 || rightRank < leftRank)) {
                best = Math.max(best, dp[left] + dp[right] + 1);
            }

            // Option: pick right winner, left must have lower rank (or -1)
            if (rightRank != -1 && (leftRank == -1 || leftRank < rightRank)) {
                best = Math.max(best, dp[left] + dp[right] + 1);
            }

            // If both are -1, we can keep 0
            if (leftRank == -1 && rightRank == -1) {
                best = Math.max(best, dp[left] + dp[right]);
            }

            // Also consider cases where one side is -1 and the other is not
            if (leftRank == -1 && rightRank != -1) {
                best = Math.max(best, dp[left] + dp[right] + 1);
            }
            if (rightRank == -1 && leftRank != -1) {
                best = Math.max(best, dp[left] + dp[right] + 1);
            }

            dp[i] = best;

            // Determine the rank of this node (winner's rank)
            // If both children have same rank, that rank propagates
            if (leftRank != -1 && leftRank == rightRank) {
                nodeRank[i] = leftRank;
            } else if (leftRank != -1 && (rightRank == -1 || leftRank > rightRank)) {
                nodeRank[i] = leftRank;
            } else if (rightRank != -1 && (leftRank == -1 || rightRank > leftRank)) {
                nodeRank[i] = rightRank;
            } else {
                nodeRank[i] = -1; // undetermined
            }
        }

        // dp[1] gives maximum number of teams that can stay with correct rank
        int maxCorrect = dp[1];
        int minChanges = totalTeams - maxCorrect;
        System.out.println(minChanges);
    }
}

