public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] groups = new int[m];
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt(), b = sc.nextInt();
            groups[i] = b - a + 1;
        }
        Arrays.sort(groups);
        // consistent sizes: 1,1,2,4,...,2^(n-1)
        List<Integer> consistent = new ArrayList<>();
        consistent.add(1); consistent.add(1);
        for (int i = 1; i < n; i++) consistent.add(1 << i);
        // Greedy: for each consistent bin, fill with received groups
        int total = 1 << n;
        int kept = 0;
        boolean[] used = new boolean[m];
        for (int c : consistent) {
            int rem = c;
            for (int i = m-1; i >= 0 && rem > 0; i--) {
                if (!used[i] && groups[i] <= rem) { used[i]=true; kept+=groups[i]; rem-=groups[i]; }
            }
            kept += (c - rem) - (c - rem); // already counted
            // fill remaining with partial
            for (int i = m-1; i >= 0 && rem > 0; i--) {
                if (!used[i]) { used[i]=true; int take=Math.min(groups[i],rem); kept+=take; rem-=take; }
            }
        }
        System.out.println(total - kept);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int n, m, N;
    static int[] rankByTeam;
    static int[][] dp;
    static final int INF = 1_000_000_000;

    // Returns maximum number of teams in interval [l, r)
    // that can keep their current rank values while making this interval consistent.
    static int solve(int l, int r) {
        if (r - l == 1) return 1;
        if (dp[l][r] != -1) return dp[l][r];

        int mid = (l + r) >>> 1;
        int left = solve(l, mid);
        int right = solve(mid, r);

        int len = r - l;
        int roundRank = n - Integer.numberOfTrailingZeros(len);

        int keepLeftWinner = 0;
        for (int i = l; i < mid; i++) {
            if (rankByTeam[i] == roundRank) keepLeftWinner = 1;
        }
        int keepRightLosers = 0;
        for (int i = mid; i < r; i++) {
            if (rankByTeam[i] != roundRank) keepRightLosers++;
        }
        int option1 = left + right + keepLeftWinner + keepRightLosers;

        int keepRightWinner = 0;
        for (int i = mid; i < r; i++) {
            if (rankByTeam[i] == roundRank) keepRightWinner = 1;
        }
        int keepLeftLosers = 0;
        for (int i = l; i < mid; i++) {
            if (rankByTeam[i] != roundRank) keepLeftLosers++;
        }
        int option2 = left + right + keepRightWinner + keepLeftLosers;

        return dp[l][r] = Math.max(option1, option2);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        m = fs.nextInt();
        N = 1 << n;

        rankByTeam = new int[N];

        // Input describes m segments:
        // a teams in a row have rank b
        int idx = 0;
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            for (int j = 0; j < a; j++) {
                rankByTeam[idx++] = b;
            }
        }

        dp = new int[N + 1][N + 1];
        for (int i = 0; i <= N; i++) Arrays.fill(dp[i], -1);

        int maxKeep = solve(0, N);
        int minChanges = N - maxKeep;
        System.out.println(minChanges);
    }
}
